+    let d = (pts[0].0, pts[pts.len() - 1].0);
+    let s_p = f.station_of(parting_z);
+    let side = waste_side(d, s_p, tol, stock);
+    let half = width * 0.5;
+    for (i, m) in path.moves.iter().enumerate() {
+        if m.kind == MoveKind::Rapid {
